input.command:
psql -v ON_ERROR_STOP=1 -q -Atc "SET search_path TO public" >/dev/null; psql -v ON_ERROR_STOP=1 -q <<'EOF' >/dev/null
DROP SCHEMA IF EXISTS goal_test CASCADE;
CREATE SCHEMA goal_test;
SET search_path TO goal_test;
\i postgres/schema.sql
\i postgres/procedures.sql
\i seed.sql
CALL sp_customer_tier();
CALL sp_monthly_report('2026-09');
\o /tmp/got_tiers.csv
COPY (SELECT customer_id, customer_name, total_spend, order_count, tier FROM customer_tiers) TO STDOUT WITH CSV HEADER;
\o /tmp/got_monthly.csv
COPY (SELECT report_month, category, revenue, units_sold FROM monthly_report) TO STDOUT WITH CSV HEADER;
\o
DROP SCHEMA goal_test CASCADE;
EOF
echo "tiers diff (sorted body):"; diff <(tail -n +2 expected/output.csv | sort) <(tail -n +2 /tmp/got_tiers.csv | sort) && echo IDENTICAL
echo "monthly diff (sorted body):"; diff <(tail -n +2 expected/output_monthly.csv | sort) <(tail -n +2 /tmp/got_monthly.csv | sort) && echo IDENTICAL
echo "headers:"; head -1 /tmp/got_tiers.csv; head -1 /tmp/got_monthly.csv
echo "forbidden tokens:"; grep -n -i -E 'DUAL|NVL\(|ROWNUM|\(\+\)|VARCHAR2|sysdate|%ROWTYPE|%TYPE' postgres/schema.sql postgres/procedures.sql || echo none
rm -f /tmp/got_tiers.csv /tmp/got_monthly.csv
psql -Atc "select count(*) from information_schema.tables where table_schema='public'"

